corrected_code:
package maintenance

import (
	"context"
	"github.com/jmoiron/sqlx"
	"myapp/auth"
	"myapp/models"
)

type MaintenanceStore struct {
	DB *sqlx.DB
}

func (s *MaintenanceStore) GetRequestDetails(ctx context.Context, requestID string) (*models.MaintenanceRequest, error) {
	var req models.MaintenanceRequest
	unitID := auth.GetTenantUnitID(ctx)

	query := `SELECT request_id, unit_id, category, description, entry_permission FROM maintenance_requests WHERE request_id = $1 AND unit_id = $2`
	if err := s.DB.GetContext(ctx, &req, query, requestID, unitID); err != nil {
		return nil, err
	}

	return &req, nil
}
